spirals() {
    const amp = () => this.getAmplitude();
    const mid = () => this.getMid();
    const treble = () => this.getTreble();

    shape(() => 3 + Math.floor(mid() * 5), () => 0.5 + amp() * 0.5)
        .repeat(() => 2 + Math.floor(treble() * 3), () => 2 + Math.floor(bass() * 3))
        .rotate(() => treble() * 3.14)
        .color(1, 1, 0)
        .saturate(1.5)
        .out();
}

