// 'nest' is only a creative, arbitrary name
nest = (freq,div) => {
  	nest = osc(freq,.02); step = Math.PI*2/div
	for(i = 1; i<div; i++){
      r = i*step;
      nextOsc = osc(freq,.02).rotate(r);
      if(r<Math.PI) nextOsc.invert();
      nest.diff(nextOsc);
      if(i%2==0) nest.colorama(.06)
    }
  	return nest;
}
